INSERT INTO `achievement_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `Reward_lang`, `VerifiedBuild`) VALUES
(63325, 'ptBR', 'Obter 5 Grânulos de Inquirição do Omnium para usar no Fólio do Omnium.', 'Estudos do Fólio do Omnium', 'Decoração: simulacro do Omnium dos Andassol', 68974),
(62903, 'ptBR', 'Dissipar 5 Tempestades em Val.', 'Lambanças climáticas: Val', 'Mascote de recompensa: desbloqueia Keith Palipeixe para a compra', 68974),
(63343, 'ptBR', 'Marcar um gol com a Bola de Treino Chutável em Luaprata enquanto usa um Tabardo de Participação.', 'Gol!', 'Decoração: Orbe Precioso de Azeroth, Orgulho da Horda Emoldurado e Orgulho da Aliança Emoldurado', 68974),
(61336, 'ptBR', 'Reverenciar as chamas de Midnight.', 'Guardião das Chamas de Midnight', '', 68974),
(61335, 'ptBR', 'Reverenciar as chamas de Midnight.', 'Protetor das Chamas de Midnight', '', 68974),
(61936, 'ptBR', 'Derrotar a Vanguarda Cegada pela Luz enquanto o raide inteiro estiver com Aura Máxima na Torre do Caos e no modo Normal ou superior.', 'Geração de aura', '', 68974),
(61911, 'ptBR', 'Derrotar Vaelgor e Ezzorak depois de todos os jogadores romperem cada aprisionamento da Zona Abissal em até 3 segundos na Torre do Caos e no modo Normal ou superior.', 'Preparar, apontar, arrebentar!', '', 68974),
(61514, 'ptBR', 'Derrotar o Rei Caído Salhadaar depois que todos se /ajoelharem para ele antes do início da luta na Torre do Caos no modo Normal ou superior.', 'É traição, então', '', 68974),
(61381, 'ptBR', 'Derrotar Belo\'ren, Filho de Al\'ar, depois de imbuir o Ovo da Nascente do Sol com magia de Luz e Caos na Marcha em Quel\'Danas no modo Normal ou superior.', 'Crise ovistencial', '', 68974),
(61346, 'ptBR', 'Derrotar Coroa do Cosmos após matar uma Monstruosidade de Carne e devolver toda a carne dela ao Vazio na Torre do Caos no modo Normal ou superior.', 'Pode apostar que isso vai ter volta', '', 68974),
(61611, 'ptBR', 'Derrotar Queda da Meia-noite na Marcha em Quel\'Danas no modo Mítico em um grupo da guilda.', 'Mítico: Incursão de Guilda na Queda da Meia-noite', '', 68974),
(61380, 'ptBR', 'Obter as conquistas de raide indicadas abaixo.', 'Glória do Saqueador de Midnight', 'Montaria: Consternador Tenebroso', 68974),
(62874, 'ptBR', 'Obter as conquistas abaixo:', 'Uma viagem através das estrelas', 'Recompensa: desbloqueia Nulitraje de Forjetérea para a compra', 68974);
INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(909, 'ptBR', 'Fólio do Omnium - Novas informações', 'Os magísteres têm informações adicionais que podem potencializar mais runas no Fólio do Omnium.', 'Aceitar missão', 'Concede um Grânulo de Inquirição do Omnium para potencializar outra runa no Fólio do Omnium.', '', 68974);
INSERT INTO `area_table_locale` (`ID`, `locale`, `AreaName_lang`, `VerifiedBuild`) VALUES
(15966, 'ptBR', 'Covil de Predaxas', 68974);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(4618, 'ptBR', 'MODO DE RELAXAMENTO: ATIVADO.\nNÍVEL DE RELAXAMENTO: MÁXIMO.\nTEMPERATURA INTERNA: BAIXA.', '|cFFFFD200Promoção|r |n', 68974),
(4617, 'ptBR', 'DIRETIVA PRIMÁRIA: PARTICIPAR DE HEROÍSMOS.\nHEROÍSMOS PREFERIDOS: COM EMOÇÃO.\nDIRETIVA SECUNDÁRIA: VIRAR HERÓI.\nHERÓI PREFERIDO: GRANDÃO.', '|cFFFFD200Promoção|r |n', 68974),
(4949, 'ptBR', 'Vestígio duradouro da tentativa de Fyrakk de corromper Amirdrassil.', '|cFFFFD200Comerciante: |rXydan|n|cFFFFD200Área: |rValdrakken|n|cFFFFD200Custo: |r2200|Hcurrency:1166|h|TInterface\\ICONS\\PVECurrency-Justice.blp:0|t|h', 68974),
(5074, 'ptBR', 'Diferentemente da maioria dos emissários do Caos na Tempestade do Caos, Silento prefere a paz e o sossego do silêncio... mesmo que isso implique silenciar seus parentes mais tagarelas.', '|cFFFFD200Conquistas:|r Sucesso em Batalhas Decisivas: Val e Sucesso em Batalhas Decisivas: Naigtal|n|cFFFFD200Comerciante: |rKifaan|n|cFFFFD200Áreas: |rVal ou Naigtal|n|cFFFFD200Custo: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(5073, 'ptBR', 'Na tentativa de estar à altura de seus ancestrais, essa pequenina está pronta para entrar em frenesi. Ela vai começar com aranhinhas e ir subindo a partir daí.', '|cFFFFD200Conquista:|r Chacina de Ultradon|n|cFFFFD200Comerciante: |rKifaan|n|cFFFFD200Áreas: |rVal ou Naigtal|n|cFFFFD200Custo: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(4898, 'ptBR', 'Peixes congelados são o lanchinho favorito de Keith. Se você tiver peixes congelados, vai arranjar um novo melhor amigo.', '|cFFFFD200Conquista:|r Lambanças climáticas: Val|n|cFFFFD200Comerciante: |rKifaan|n|cFFFFD200Área: |rNaigtal ou Val|n|cFFFFD200Custo: |r50|Hitem:238365|h|TInterface\\ICONS\\INV_Misc_Fish_41.blp:0|t|h |n|n', 68974);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(317639, 'ptBR', 'O Comandante Tala\'saan despoja-se de seu manto de lumivéu e dá um passo à frente.', '', 68974),
(314421, 'ptBR', 'AUGH!', '', 68974),
(314420, 'ptBR', 'CUIDADO, SOBRINHO!', '', 68974),
(314419, 'ptBR', 'NEM dos HASH\'EY!', '', 68974),
(314418, 'ptBR', 'Com esse poder, a gente NÃO precisa dos LOAS,', '', 68974),
(314417, 'ptBR', 'Não!', '', 68974),
(314416, 'ptBR', 'Solta ela!', '', 68974),
(314415, 'ptBR', 'Isso é magia negra!', '', 68974),
(314414, 'ptBR', 'Zul\'jan!', '', 68974),
(314413, 'ptBR', '(grunhido)', '', 68974),
(314412, 'ptBR', 'Deve ser... a chave pra...', '', 68974),
(314411, 'ptBR', 'Achei!', '', 68974),
(314410, 'ptBR', 'Ah!', '', 68974),
(314408, 'ptBR', 'eu garanto... que ela vai entender.', '', 68974),
(314407, 'ptBR', 'Quando você tiver o poder da Ula\'tek,', '', 68974),
(314406, 'ptBR', 'Pega a chave, Zul\'jan.', '', 68974),
(314405, 'ptBR', 'Quando ela olhar o nosso tio...', '', 68974),
(314404, 'ptBR', 'Os loas tão com ela na palma da mão...', '', 68974),
(314403, 'ptBR', 'E... E a minha irmã?', '', 68974),
(314402, 'ptBR', 'Pra terminar o que eu e o teu avô começamos.', '', 68974),
(314401, 'ptBR', 'sem as promessas vãs dos loas.', '', 68974),
(314400, 'ptBR', 'Pra garantir o futuro do nosso povo,', '', 68974),
(314399, 'ptBR', 'E preciso da tua ajuda, Zul\'jan.', '', 68974),
(314398, 'ptBR', 'Malacrass.', '', 68974),
(314397, 'ptBR', 'Isso...', '', 68974),
(314396, 'ptBR', 'Então tu deve ser...', '', 68974),
(314395, 'ptBR', 'Tu conheceu meu avô?', '', 68974),
(314394, 'ptBR', 'Eu e o Zul\'jin tentamos mudar isso...', '', 68974),
(314393, 'ptBR', 'Infelizmente, é esse o destino do nosso povo.', '', 68974),
(314392, 'ptBR', 'Mas onde eles tavam quando ele deu o último suspiro?', '', 68974),
(314391, 'ptBR', 'Uma vida dedicada aos loas...', '', 68974),
(314390, 'ptBR', 'Trágico.', '', 68974),
(314389, 'ptBR', 'Não, não, não. Eu não...', '', 68974),
(314388, 'ptBR', 'Não...', '', 68974),
(314387, 'ptBR', 'Ele morreu, Zul\'jan.', '', 68974),
(314386, 'ptBR', 'Ahr... TIO!', '', 68974),
(314385, 'ptBR', 'Ahrrr... Tio!', '', 68974),
(314384, 'ptBR', '(tossindo)', '', 68974),
(310355, 'ptBR', 'E eu vou procurar essa peça faltante na Torre Aurestela. Venha comigo quando puder, $n. E, Rommath, boa sorte.', '', 68974),
(318038, 'ptBR', 'Você viu a vigilante? Encontramos uma maneira de desentrelaçar a grade sem destruir as almas ou o núcleo dela!\n\nY\'mera e eu conseguimos usar a grade para forjar um novo núcleo arcano para o nulitraje.\n\nFascinante, não é mesmo?', '', 68974),
(317801, 'ptBR', '<Tala\'saan pondera a pergunta, com a expressão distante por um breve momento.>\n\nA Capitã Fareeya não participará desta operação.\n\nEu atuo em nome dela perante os Forjados a Luz destacados para a missão de Maella.\n\nCom a perda do Alto-exarca e de incontáveis outros, o Exército da Luz necessita da liderança dela agora mais do que nunca.\n\nFelizmente, não estamos inteiramente sós. Como viste, Baraat e Y\'mera juntaram-se a nós.\n\nEnaara liberou ambos depois de muitos protestos, mas ela também ficará para trás com Sorvos e a capitã.', '', 68974),
(317797, 'ptBR', '<A expressão de Tala\'saan se torna mais tensa.>\n\nMuitos de meus irmãos e irmãs... se perderam no vórtice ululante da Torre do Caos.\n\nE outros mais sofreram ferimentos que vão além do físico.\n\nSei o que se abateu sobre muitos daqueles dentro da torre, $n. Tu também viste, não viste? Fúria... confusão... desespero.\n\nPerdemos muitas boas almas nesta guerra. Eu não poderia pedir a Fareeya que cedesse mais do que podia.', '', 68974),
(317795, 'ptBR', 'Sou Tala\'saan, Comandante do Lumivéu no Exército da Luz.\n\nA pedido de Fissulâmina Maella, aceitei integrar a perseguição destas forças do Caos e dos Hal\'hadar.\n\nTemos uma história atribulada com esses inimigos, mas somos bem preparados para nos embrenhar em reinos desconhecidos.\n\nAqueles que vês reunidos aqui estão entre os melhores a servir na unidade do Lumivéu.', '', 68974),
(317656, 'ptBR', '', 'Tul\'amar range os dentes enquanto mergulha em silêncio por um momento. Seu olho bom volta-se para você e logo retorna a Tala\'saan.', 68974),
(317572, 'ptBR', 'Vou vigiar de perto o meu — ou melhor — o nosso novo peão.', '', 68974),
(317571, 'ptBR', 'Nosso trabalho ainda não está completo, mas não tema a intromissão de Impotus. Ele vai se trancafiar na Acrópole, saboreando a vitória.', '', 68974),
(317109, 'ptBR', 'Este casebre glacial é insignificante. Existem outros mundos que seriam bem mais fáceis... e mais ideais.', '', 68974),
(316762, 'ptBR', 'A Fissulâmina Maella pediu que acompanhássemos as tropas dela nesta expedição.\n\nO conhecimento de Veraan sobre o Caos e sobre as operações do Hal\'hadar a tornaram um ativo valioso para esta missão.\n\nE eu? Bom, nunca se sabe quando um tecnomante será necessário pra destroçar algo!', '', 68974),
(316750, 'ptBR', '', 'Os arquivos em Antorus revelaram que a presença da Legião aqui em Val era escassa. Não consigo imaginar o motivo.\n\nGrande parte do planeta é protegida por chuvas de granizo pesadas, capazes de perfurar os cascos das naves da Legião.\n\nAo menos duas embarcações da invasão se perderam na tentativa de reivindicar este mundo.\n\nEles acabaram estabelecendo alguns baluartes, apesar de não serem nada além de postos avançados remotos.\n\nAparentemente, os que eram alocados nos postos avançados de Val eram enviados para cá como punição por repetidos fracassos.', 68974),
(316562, 'ptBR', '', '<A Arquimaga Y\'mera aparenta estar focada na missão, introduzindo símbolos rúnicos no console com mãos que mais parecem um borrão.>\n\nA energia do Caos ao sul tem origem na Acrópole. \n\nSegundo essas leituras, a fortaleza desce fundo sob o gelo.', 68974),
(316520, 'ptBR', '', 'Os Illidari conhecem melhor do que ninguém este inferno congelado. A Legião se referia a este lugar como \"Val\" e usava a temperatura congelante para interrogar prisioneiros.\n\nUm deserto frio e sem vida parece o lugar perfeito para um domanaar se esconder.\n\n<Maella lança um olhar não tão sutil na direção de Decimus.>', 68974),
(316419, 'ptBR', '<Há dois botões para escolher o destino do teleporte: Luaprata ou Tempestade do Caos. Resista ao desejo de pressionar os dois simultaneamente.>', '<Há dois botões para escolher o destino do teleporte: Luaprata ou Tempestade do Caos. Resista ao desejo de pressionar os dois simultaneamente.>', 68974),
(316274, 'ptBR', '', 'Graças aos holodiagramas que você recuperou, sabemos onde os etéreos estão obtendo os artefatos draeneicos.\n\nHá uma cripta construída pelo meu povo sob a ilha.\n\nOs Hal\'hadar estão extraindo dela tanto os guardiões quanto os espíritos perturbados dos mortos.\n\nOs registros indicam que há vários vigilantes no túmulo, mas até agora os esforços deles não tiveram sucesso.\n\nSe tivermos sorte, talvez seja possível interceptar essas operações.\n\nTala\'saan liderará nossa incursão na cripta.', 68974),
(316214, 'ptBR', '', '<A Arquimaga Y\'mera arregala os olhos enquanto pega um dos cristais com você.>\n\nEssas runas são draenorianas, $n. Não devia ser surpresa.\n\nOs Hal\'hadar são abutres quando o assunto é tecnologia. Reviram as ruínas de qualquer mundo em que desçam.\n\nEles devem ter encontrado a tecnologia de cristais do nosso povo em outro lugar, assim como nossos mecatrajes.\n\nExaminarei isto aqui. Leva o restante para Kifaan, ali. Ele está documentando a tecnologia dos Hal\'hadar.\n\nSerá bom ter a opinião de um tecnomante do Consórcio a respeito dessa descoberta.', 68974),
(316212, 'ptBR', '', '<A Arquimaga Y\'mera aparenta estar focada na missão, introduzindo símbolos rúnicos no console com mãos que mais parecem um borrão.>\n\nCom um pouco de sorte e muita decodificação, poderemos entender o que nossos inimigos querem conseguir em Naigtal.\n\nHá muito a se aprender sobre os Hal\'hadar, $Ucampeão:campeã;.\n\nNão podemos perder esta oportunidade.', 68974),
(314754, 'ptBR', 'Seus inimigos estão atrás de você. Dê meia-volta!', 'Seus inimigos estão atrás de você. Dê meia-volta!', 68974),
(313932, 'ptBR', '', 'A Fissulâmina Maella encara intensamente a projeção de Decimus.', 68974),
(313749, 'ptBR', '', 'Já é hora? A Fissulâmina Maella te enviou? Tua ajuda viria a calhar antes da partida!\n\nVenho trabalhando em modificações das nossas tecnologias de lumivéu com um simples feitiço de camuflagem e aquela amarra.\n\nCreio que, combinados, sejam capazes de camuflar todo o nosso acampamento quando chegarmos.\n\nMas, primeiro, preciso de uma cobaia invisível para testar os limites de alcance da amarra.\n\nAceitas ajudar?', 68974),
(310380, 'ptBR', 'Extinguir um imperador domanaar não tem o mesmo impacto que matar um líder mortal.', '', 68974),
(310377, 'ptBR', '', 'Pertinax não será mais um problema para nós, graças a um certo alguém aqui.', 68974),
(310376, 'ptBR', 'Se o \"Imperador\" deles der o ar da graça, eu ficaria muito feliz se você o removesse destes ermos.', '', 68974),
(310375, 'ptBR', '', 'Neutralizar a presença do Caos aqui faz ganhar tempo para nosso povo lá em casa descansar. Semeie a discórdia, combatente.', 68974),
(310366, 'ptBR', 'Luz... vileza... Caos. É a receita perfeita para agravar a tensão. Que delícia.', '', 68974),
(309048, 'ptBR', 'Os Hal\'hadar armaram seus esquifes voadores com torretas de energia para se \"protegerem\". Vejamos se estão protegidos, que tal?', '', 68974),
(309047, 'ptBR', 'Sei pouquíssimo sobre esses \"Hal\'hadar\", mas eles parecem mais terríveis que a Guarda Sombria. Sugiro que diminua os números deles para que não te sobrepujem no futuro.', '', 68974),
(309020, 'ptBR', '', 'Nossos batedores Forjados a Luz relataram indícios de que uma criatura ancestral do Caos viveu aqui. Colete amostras para nossa pesquisa, pode ser?', 68974),
(309018, 'ptBR', 'Os seus batedores mais... \"aventureiros\" tentaram aproveitar os recursos voláteis deste mundo. Tente não causar um acidente infeliz durante a coleta.', '', 68974),
(309015, 'ptBR', '', 'Sabotar a rede de portais dos domanaar deve atrapalhar a invasão deles a Azeroth. Faça o que puder para desacelerá-los.', 68974),
(309014, 'ptBR', 'Não surpreende que outra \"ameaça\" ponha a sua missão em perigo. Destrua, elimine e vença.', '', 68974),
(318546, 'ptBR', 'O Terraço dos Magísteres sempre foi um lugar dedicado ao aprendizado.\n\nUm bastião de conhecimento, onde ideias podem ser compartilhadas sem divisões ou vaidade.\n\nE, no entanto, por mais que eu tente, é difícil olhar para aqueles que retornaram e não sentir...\n\n<O magíster cerra os dentes e permanece em silêncio.>', 'O Terraço dos Magísteres sempre foi um lugar dedicado ao aprendizado.\n\nUm bastião de conhecimento, onde ideias podem ser compartilhadas sem divisões ou vaidade.\n\nE, no entanto, por mais que eu tente, é difícil olhar para aqueles que retornaram e não sentir...\n\n<O magíster cerra os dentes e permanece em silêncio.>', 68974),
(318542, 'ptBR', '<O magíster elfo superior suspira à medida que você se aproxima.>\n\nFaça-me o favor de não berrar comigo por estar aqui... Eu não suportarei outro olhar torto ou comentário.\n\nEu quero apenas aprender magia e praticar novos feitiços. É pedir demais?\n\nToda esta contenda está me deixando maluco!', '<O magíster elfo superior suspira à medida que você se aproxima.>\n\nFaça-me o favor de não berrar comigo por estar aqui... Eu não suportarei outro olhar torto ou comentário.\n\nEu quero apenas aprender magia e praticar novos feitiços. É pedir demais?\n\nToda esta contenda está me deixando maluco!', 68974),
(317974, 'ptBR', 'Dominar e compreender a magia foi sempre o nosso caminho. O caminho dos Magísteres.\n\nEu espero que alguns de nossos irmãos de mente mais aberta possam ajudar os outros a entenderem nossas intenções ao estudar o Caos.\n\nAlém do mais, não temos a menor intenção de ameaçar de exílio aqueles que não queiram tomar parte nestes estudos.', 'Dominar e compreender a magia foi sempre o nosso caminho. O caminho dos Magísteres.\n\nEu espero que alguns de nossos irmãos de mente mais aberta possam ajudar os outros a entenderem nossas intenções ao estudar o Caos.\n\nAlém do mais, não temos a menor intenção de ameaçar de exílio aqueles que não queiram tomar parte nestes estudos.', 68974),
(317973, 'ptBR', 'De acordo com Veldharin, os primeiros Buscadores do Conhecimento investigaram a presença sombria que nossos ancestrais sentiam em Tirisfal.\n\nNinguém sabe ao certo o que eles encontraram, mas aparentemente apenas alguns deles retornaram com as mentes intactas.\n\nO que quer que tenham visto ou encontrado foi suficiente para que Dath\'Remar proibisse a magia do Caos.\n\nVocê crê que Umbric possa ter perscrutado essas profundezas? Será que teremos permissão para isso?', 'De acordo com Veldharin, os primeiros Buscadores do Conhecimento investigaram a presença sombria que nossos ancestrais sentiam em Tirisfal.\n\nNinguém sabe ao certo o que eles encontraram, mas aparentemente apenas alguns deles retornaram com as mentes intactas.\n\nO que quer que tenham visto ou encontrado foi suficiente para que Dath\'Remar proibisse a magia do Caos.\n\nVocê crê que Umbric possa ter perscrutado essas profundezas? Será que teremos permissão para isso?', 68974),
(317972, 'ptBR', '<O magíster suspira à medida que você se aproxima.>\n\nFaça-me o favor de não berrar comigo por estar aqui... Eu não suportarei outro olhar torto ou comentário.\n\nEu quero apenas aprender magia e praticar novos feitiços. É pedir demais?\n\nToda esta contenda está me deixando maluco — e isso está vindo de alguém que já ficou cara a cara com um buraco negro!', '<O magíster suspira à medida que você se aproxima.>\n\nFaça-me o favor de não berrar comigo por estar aqui... Eu não suportarei outro olhar torto ou comentário.\n\nEu quero apenas aprender magia e praticar novos feitiços. É pedir demais?\n\nToda esta contenda está me deixando maluco — e isso está vindo de alguém que já ficou cara a cara com um buraco negro!', 68974),
(317917, 'ptBR', 'Com toda sinceridade, não estou certo de que era essa a intenção dele.\n\nSua traição contra a Assembleia e nosso povo foi nauseante, porém não consigo vê-lo desejando causar dano ao Omnium.\n\nUm repositório contendo conhecimento proibido que há muito lhe fora negado não é algo que ele buscaria destruir.\n\nNa verdade, era de se esperar que ele tentasse se apossar do Omnium por completo.\n\nTalvez por isso ele tenha se contentado com apenas um pedaço.', '', 68974),
(317753, 'ptBR', '<Estreitando os olhos vítreos.>\n\nUma pergunta... adequada.\n\nÉ — era — uma fonte de conhecimento rigorosamente proibida, por decreto de Dath\'Remar.\n\nQuando pisamos pela primeira vez nas praias de Tirisfal, nossos ancestrais encontraram uma escuridão agarrada a esta terra.\n\nOs sussurros levaram muitos à loucura, alimentando-se da nossa paranoia e instigando medo e ciúme entre nosso povo cansado.\n\nDath\'Remar buscou compreender de onde vinha essa magia e, por isso, enviou os primeiros Caçadores.\n\nPoucos sabem o que encontraram ou enfrentaram, mas foi o suficiente para Dath\'Remar encerrar seus estudos.\n\nSomente os magísteres mais confiáveis e talentosos tinham permissão para sondar o conhecimento contido na Magícula do Caos.', '', 68974),
(317750, 'ptBR', 'Excelente pergunta! Vejamos...\n\nTemos a Magícula Arcana, é claro. Milhares de anos de conhecimento dos altaneiros deram ao nosso jovem povo os recursos para prosperar nesta nova terra.\n\nTemos as Magículas do fogo e dos outros elementos: os fundamentos naturais do próprio mundo.\n\nTemos uma curiosa coleção de saberes sagrados na Magícula da Luz. Os Sumos Sacerdotes de Luaprata contribuíram muito para o conhecimento sobre ela.\n\nE, já que todos sempre perguntam, temos as Magículas proibidas...\n\nCaos, Vileza, Necromancia... embora eu imagine que algumas das restrições sobre eles possam ser... afrouxadas.\n\n<Veldharin franze a testa, pensativo.>', '', 68974),
(317749, 'ptBR', 'Sugiro que você leia aquela placa ali, no Omnium. Ela resume muito bem as intenções de Dath\'Remar.\n\nMas, em suma, suas razões eram muitas, suas ambições eram ousadas, e seu propósito era tão claro quanto os céus que recobrem o Canto Eterno.\n\nDath\'Remar viu muito em sua juventude e não quis se esquivar das forças mágicas do nosso mundo.', '', 68974),
(317748, 'ptBR', 'Claro que sim, e não só pelo Omnium!\n\nPerdi dois irmãos e minha querida irmã quando a cidade caiu. Os três eram magísteres...\n\nTentei ajudar o jovem príncipe a reviver... ou seria despertar? Estava tão... frio.\n\nMas apesar dos nossos esforços, ele simplesmente... recusava. Não respondia nem mesmo com a cifra-chave dele.\n\nDepois que foi selado, tentei ajudar os magísteres sobreviventes a restaurar o Terraço... mas eles insistiram que eu descansasse.\n\nE assim o fiz por muitos anos. Alguns bons, outros... nem tanto. Mas, enfim, voltei, e o jovem Rommath não estava disposto a tentar me impedir.\n\nDesaposentar era exatamente o que eu precisava depois de tantos anos!', '', 68974),
(317746, 'ptBR', 'Bom, quando insisti que fizesse uma pergunta, eu quis dizer sobre o Omnium, não sobre mim. Mas, se você tem tanto interesse...\n\nSou o Custódio Veldharin, nomeado Guardião do Saber pelo Grão-magíster... ehh... qual deles mesmo?\n\nOu foi a Grã-magistra Mo — não, ela não. Ah... Vários grão-magísteres atrás. Claramente, já perdi a conta.\n\nDepois da Segunda Guerra, fui... incentivado a me aposentar. Pelo visto, Anasterian queria que eu \"aproveitasse os muitos dias que ainda me restavam\".\n\nEra o jeito dele de dizer que eu estava velho demais para o cargo. Então fui morar com minha filha, Elsharin.\n\nEla serviu como Perscrutadora do Conhecimento e Embaixadora Magisterial no Sacrário dos Teurgos, em Ventobravo.', '', 68974),
(317744, 'ptBR', 'Boas-vindas ao Licaneu!\n\nVocê está diante de uma infinitude de conhecimento e potencial mágico!\n\nNaturalmente, refiro-me ao Omnium dos Andassol. \n\nSou apenas seu humilde guardião, à postos para responder e orientar todos os jovens magísteres em sua jornada acadêmica e mágica.\n\nSe tiver alguma pergunta, fique à vontade.', '', 68974),
(317738, 'ptBR', 'Por que você acha que chamam isso de magículas? Por que não manáculos? Aliás, assim fica parecendo manacás.\n\nOmnículas, como em partículas? Ou seria Omnícolas?\n\nDath\'Remar me acuda, será que eu sempre falei isso tudo errado?', 'Por que você acha que chamam isso de magículas? Por que não manáculos? Aliás, assim fica parecendo manacás.\n\nOmnículas, como em partículas? Ou seria Omnícolas?\n\nDath\'Remar me acuda, será que eu sempre falei isso tudo errado?', 68974),
(317730, 'ptBR', 'Não vejo tanto caos mágico no Terraço desde... bom... sua aventura com Magíster Umbric.\n\n<O quebra-feitiço observa você dos pés à cabeça.>\n\nDesta vez, trate de se comportar.', 'Não vejo tanto caos mágico no Terraço desde... bom... sua aventura com Magíster Umbric.\n\n<O quebra-feitiço observa você dos pés à cabeça.>\n\nDesta vez, trate de se comportar.', 68974),
(317724, 'ptBR', 'Contenha-se nestes salões, $c. \n\nEste pode ser o Terraço dos Magísteres, mas as regras da magia continuam sendo rigorosamente aplicadas.', 'Contenha-se nestes salões, $c. \n\nEste pode ser o Terraço dos Magísteres, mas as regras da magia continuam sendo rigorosamente aplicadas.', 68974),
(317723, 'ptBR', '<O quebra-feitiço estreita os olhos ao encarar você e esboça um leve sorriso presunçoso.>\n\nNão se preocupe, $n. Não erguerei minha glaive contra você.\n\nDisseram-me que você tinha a autoridade do Lorde-regente em sua última visita aqui. Saiba que minha reação não foi pessoal.\n\nEu honro o juramento dos quebra-feitiços, e aquela... infeliz sequência de eventos no Terraço deveria ter ficado entre as Cortes e os magísteres, não entre mim e você.\n\nNo entanto, agradeço por não ter me matado.', '', 68974),
(317722, 'ptBR', '<Rommath estreita os olhos por um instante.>\n\nUmbric e seus... seguidores terão que respeitar os regulamentos no que diz respeito ao Omnium.\n\nNão tolerarei uma ostentação mágica dos horrores do Caos só porque os ren\'dorei não conseguem seguir regras.\n\nAinda assim, embora eu tenha pouca fé no caminho seguido por Umbric, talvez eu esteja disposto a confiar nele... por ora.\n\nO controle do Caos, que ele insiste ter sido dominado pelo seu povo, talvez permita discussões mais... instruídas sobre a Magícula do Caos.\n\nMas não permitirei que a magia do Caos se torne uma nova disciplina para os magísteres deste Terraço!', '', 68974),
(317721, 'ptBR', 'Somente os magísteres têm permissão para estudar o conhecimento contido ali e, mesmo assim, com restrições.\n\nRegras e regulamentos foram instituídos pelo próprio Dath\'Remar gerações atrás.\n\nIsso garantiu que, ao descobrirmos e catalogarmos magias novas e perigosas, também nos protegêssemos da natureza imprevisível dessas forças.\n\nDito isso, houve um tempo em que acessar a Magícula Vil era terminantemente proibido.\n\nComo os tempos mudam rápido...', '', 68974),
(317719, 'ptBR', '<Umbric sorri e olha para Rommath.>\n\nRommath mal tolera minhas pesquisas, mas o Omnium sempre foi bem protegido por medidas de segurança e regulamentos.\n\nFelizmente, ele nunca foi um compêndio aberto sobre tudo que é magia.\n\nEstremeço só de pensar no que Dar\'Khan poderia ter alcançado se tivesse recebido acesso.\n\nAs regras vigentes existem desde os tempos de Dath\'Remar.\n\nSeus primeiros contatos com o Caos, ou com a devastação que testemunhou com a magia vil durante a Guerra dos Antigos, são exatamente o motivo pelo qual tais magias foram banidas.\n\nDito isso, talvez ainda haja espaço para algumas discussões.', '', 68974),
(317717, 'ptBR', 'Uma pergunta que todos nós fazemos desde que ele silenciou.\n\nNinguém sabe exatamente o que aconteceu. Só sabemos em que estado ele foi encontrado.\n\nEu não estava aqui quando o Terraço caiu... quando Dar\'Khan chegou... mas vi as consequências.\n\nNunca tinha visto o Omnium tão vazio. Nem uma centelha de poder, nem uma magícula à vista.\n\nUma armação estéril e silenciosa. Foi perturbador, para dizer o mínimo.', '', 68974),
(317715, 'ptBR', 'Quando o encontramos, não havia nada além de uma armação vazia nos destroços. Nenhuma magícula. Nenhum brilho rúnico.\n\nÀ exceção dos restos deixados pelo massacre de Dar\'Khan, parecia sem vida.\n\nAs magículas foram criadas como extensões do Omnium. Nunca as consideramos peças que pudessem desaparecer.\n\nQuando a relíquia despertou e as magículas reapareceram, notamos que a matriz central estava vazia.\n\nEra uma anomalia que nunca tínhamos visto.\n\nA última magícula acessada simplesmente desapareceu ou foi destruída. Ou, neste caso, roubada.', '', 68974),
(317714, 'ptBR', 'No início, sim. \n\nSabíamos que seu objetivo no Terraço era massacrar a Convocação. As provas disso estavam marcadas nas paredes e no próprio Omnium.\n\nMas, quando invadimos seus escritórios e sua residência, encontramos apenas a obsessão dele por magias sombrias.\n\nMais tarde, Umbric apontou que Drathir era motivado por poder e conhecimento, e danificar o Omnium parecia contrariar suas... ambições.', '', 68974),
(317713, 'ptBR', 'Eu... não tenho uma resposta para isso.\n\nMas tentamos tudo o que foi possível para reviver o Omnium. Nem mesmo a cifra-chave dos Andassol teve qualquer efeito sobre ele.\n\nKael\'thas estava... enlutado.\n\nEle, como todos nós, havia perdido muito em pouco tempo. \n\nEstava desesperado em busca de respostas para a nossa sina e para o nosso povo.\n\nO conhecimento contido no Omnium poderia ter nos ajudado... talvez até guiado o príncipe.\n\nMas, quando ele permaneceu em silêncio, chegamos a um impasse.', '', 68974),
(316792, 'ptBR', 'Cifra-chave dos Andassol não reconhecida. Registro de eco espelhado ativado.', 'Cifra-chave dos Andassol não reconhecida. Registro de eco espelhado ativado.', 68974),
(315312, 'ptBR', 'Esta é a Torre Aurestela, o lar de Dar\'Khan Drathir na infância. Foi outrora um lugar pacato, agradável.\n\nDepois do meu exílio de Luaprata, localizei várias partes da pesquisa de Dar\'Khan a respeito do Caos, as quais me trouxeram até aqui.\n\nAparentemente, ele conduziu boa parte de sua pesquisa em segredo. No topo desta torre, onde eu abri a fissura para Telogrus pela primeira vez.\n\nNão fazia ideia de que este lugar reservava ainda mais segredos...', '', 68974),
(314998, 'ptBR', 'Nunca nomeamos caçador alguém que não fosse magíster, mas você... tem uma qualificação excepcional.\n\nAgora que você é $Ucaçador:caçadora;, Umbric ou eu passaremos tarefas de pesquisa a você.\n\nEm troca, lhe daremos vários encantamentos rúnicos poderosos que deixarão você mais forte.\n\nVocê encontrará essas runas no seu Fólio do Omnium. A decisão de qual delas potencializar cabe a você, naturalmente.\n\nAlguma pergunta?', '', 68974),
(314900, 'ptBR', '<Rommath volta o olhar para o alto, para encarar o Omnium silencioso.>\n\nEstamos quase lá. Com a cifra-chave de Belo\'vir recuperada e a Magícula do Caos perdida que você e Umbric conseguiram reaver, resta só uma tarefa.\n\nÉ agora ou nunca, $n. Podemos ir a ela?', '', 68974),
(314899, 'ptBR', 'Por anos, estudei o Omnium. Como todos os magísteres antes de mim, aprendi tudo o que ele tinha a oferecer: runas, feitiços, sortilégios, o que se possa imaginar.\n\nO dia em que ele se calou foi um dia sombrio por várias razões. Nunca imaginei que voltaria a vê-lo vibrar com vida novamente. Estranho pensar em todo o caminho que percorremos.', '', 68974),
(314791, 'ptBR', 'Parece que Belo\'vir deixou instruções de como acessar o cofre... Instruções essas que estão à minha espera há muito tempo.\n\nSe conheço bem meu antecessor, ele complicou as coisas de uma maneira condizente com o seu domínio sobre o feitiço da imagem espelhada.\n\nPrecisamos dividir as tarefas aqui. Eu vou subir ao meu escritório e cuidar das proteções mais complicadas.\n\nPode ajudar as minhas imagens espelhadas a desvendar os três níveis exteriores?', '', 68974),
(314746, 'ptBR', 'Eu fico me perguntando por quanto tempo Dar\'Khan buscou os segredos proibidos na Magícula do Caos.\n\nQuando nos juntamos aos magísteres, tivemos uma aula sobre as escolas de magia, e as magículas associadas a elas eram estritamente proibidas à assembleia geral.\n\nDar\'Khan já mostrara sua inclinação ao Caos em nossos primeiros dias em Dalaran, então eu sabia que havia ao menos uma fascinação.\n\nSerá que ele a cobiçara desde aquele primeiro dia em que pisamos no Licaneu?\n\nOu terá sido uma decisão ousada de última hora após matar seus irmãos no Terraço?', '', 68974),
(314744, 'ptBR', 'Houve um tempo em que eu julgava ter desvendado todos os segredos que Dar\'Khan escondera neste lugar. Os acontecimentos de hoje decerto foram... inesperados.\n\nPor precaução — e por saber que Rommath vai perguntar do assunto —, vou garantir que não haja mais nada à espreita ou escondido aqui.\n\nVou cuidar do nosso ritual, e nos reencontramos no Terraço dos Magísteres depois que você ajudar Rommath a recuperar a cifra-chave de Belo\'vir.', '', 68974),
(314678, 'ptBR', 'Minhas desconfianças estavam corretas... Consegue sentir no ar, $n? Um pulsar frio, distante... como um batimento cardíaco abafado.\n\nAcredito que pode ser o componente que procuramos, escondido no limiar do nosso campo de visão.\n\nCom o feitiço e a concentração adequadas, o Caos pode revelar outros segredos que Dar\'Khan possa ter escondido aqui.\n\nSe fizer a gentileza de posicionar a última âncora e conectar todas elas, vou concluir este feitiço.\n\nCuidado — o Caos já nos puxa, nos chamando ao nosso destino.', '', 68974),
(310354, 'ptBR', 'Precisamos desvendar as medidas de segurança dele. Vou aguardar lá.', '', 68974),
(310059, 'ptBR', 'Fosse magia arcana, vil, até de luz ou... do Caos, Dath\'Remar criou o Omnium para preservar o conhecimento.', '', 68974),
(317919, 'ptBR', 'Imagino que muitos tenham.\n\nNormalmente, encaminho todas as perguntas ao nosso recém-desaposentado Guardião do Saber, o Custódio Veldharin.\n\nMas, considerando seu papel na restauração do Omnium, vou satisfazer sua curiosidade.', '', 68974),
(317754, 'ptBR', 'Ah, sim. A Magícula Vil. Uma fonte proibida de conhecimento. Ou era, pelo menos.\n\nA magia vil foi uma das primeiras que Dath\'Remar indicou como catalisadora para a criação do Omnium.\n\nEle viu seu potencial, e também seu horror, nos tempos dos Altaneiros, além das criaturas que empunhavam tal magia.\n\nAté que ele enxergou a realidade destrutiva tanto da magia vil quanto do arcano naqueles últimos dias da Guerra dos Antigos.\n\nA partir de então, ele nunca mais permitiria que seu povo fosse pego de surpresa por uma força destrutiva e desconhecida.\n\nCom o tempo, o conhecimento sobre a magia vil e a Legião Ardente foi compartilhado entre os magísteres e o Conselho de Tirisfal.\n\nMas, exceto para um seleto grupo, era proibido estudar a Magícula Vil.\n\nAh, como os tempos mudariam...', '', 68974),
(317573, 'ptBR', 'O mundo... todo seu potencial... agora é meu.', '', 68974),
(309931, 'ptBR', 'Patrulheiros, preparem-se! Mostrem a esses monstros por que fomos escolhidos para proteger o enclave!', 'Patrulheiros, preparem-se! Mostrem a esses monstros por que fomos escolhidos para proteger o enclave!', 68974),
(307084, 'ptBR', 'Ah, $n. \n\nÉ bom ver nesta mesa um cenho que não esteja franzido. Eles me toleram na minha cidade de novo, mas espere só para ver, a qualquer momento Rommath vai tentar usar um dos clássicos Mísseis Lampejantes dele de novo.\n\nVeja bem, ele combinou Lampejo e Mísseis Arcanos como uma lição para qualquer um que fosse tolo o bastante para desafiá-lo a um duelo de magos, em tempos idos. \n\nEle não gosta de admitir, mas fui eu quem o ensinou a aplicar um feitiço de invisibilidade aos mísseis para pegar o alvo de surpresa. \n\nDe qualquer maneira, Lor\'themar me deu permissão de comparecer, e estou aqui curtindo a aura de desconforto que os outros emitem com minha simples presença.', '', 68974),
(306595, 'ptBR', 'Nós... precisamos que Lor\'themar saiba o que houve. Vá na nossa frente.', '', 68974),
(304405, 'ptBR', 'Em tempos de guerra e conflito, nossos Ancientes Protetores provaram ser uma força implacável no campo de batalha.\n\nO único problema é que não é nada simples despertá-los.\n\nFarei com que os conservadores bélicos do Ancião Verdecasca acompanhem você. Procure pedras e penedos que o anciente possa arremessar contra nossos inimigos.\n\nEle se recusa a despertar até ter algo para arremessar.', 'Em tempos de guerra e conflito, nossos Ancientes Protetores provaram ser uma força implacável no campo de batalha.\n\nO único problema é que não é nada simples despertá-los.\n\nFarei com que os conservadores bélicos do Ancião Verdecasca acompanhem você. Procure pedras e penedos que o anciente possa arremessar contra nossos inimigos.\n\nEle se recusa a despertar até ter algo para arremessar.', 68974),
(303273, 'ptBR', '', 'Os Ancientes Protetores são poderosos e hábeis em cercos, capazes de dizimar as linhas de retaguarda inimigas.\n\nA Horda está intimamente familiarizada com o poder de destruição deles.', 68974),
(300503, 'ptBR', '', 'Não creio que isso seja possível. Enviei-a por magia a Ulen, meu senescal em comando na minha ausência. Pode haver algo errado em Suramar.', 68974),
(292933, 'ptBR', 'Bem... deu muito trabalho e você fez por merecer.', '', 68974),
(289958, 'ptBR', '', 'O Pacto de Prata volta a Luaprata uma última vez.', 68974);
