INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3033, 'ptBR', 'Engolidor Torturado', '|cFFFFD200Áreas:|r Val e Naigtal |n|cFFFFD200Conquista:|r Batalhas Decisivas heroicas|n|cFFFFD200Comerciante:|r Kifaan|n|cFFFFD200Custo: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Tanto os domanaar quando os etéreos tentaram enjaular este engolidor, mas fracassaram. Agora, impregnado de energias do Caos, engolidor torturado está pronto para espalhar a destruição.', 68974),
(2990, 'ptBR', 'Nulitraje de Forjetérea', '|cFFFFD200Conquista:|r Uma viagem através das estrelas|n|cFFFFD200Área:|r Naigtal|n|cFFFFD200Comerciante:|r Kifaan|n|cFFFFD200Custo: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Montado por Forjados a Luz, repartido pelos Hal\'hadar e restaurado por um tecnomante. Uma matriz de luz, caos e espirais arcanas dentro deste mecatraje renovado.', 68974),
(2988, 'ptBR', 'Corta-estrelas do Vidente do Caos', '|cFFFFD200Conquista:|r Uma viagem ao redor das estrelas|n|cFFFFD200Área:|r Val|n|cFFFFD200Comerciante:|r Kifaan|n|cFFFFD200Custo: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Este ápice da tecnologia de transporte dos Videntes do Caos já foi símbolo de status e poder entre os domanaar de alta posição. Após o desaparecimento misterioso de seu criador, foi considerado inconveniente quando usado em reuniões em mundos centrais.', 68974),
(2975, 'ptBR', 'Foguete de Fogos de Artifício X-TREMO de Borraquilha', '|cFFFFD200Posto Comercial|r', 'Os engenheiros da Inframina estavam tão preocupados em saber se PODIAM criar um foguete mais rápido que não pararam para se perguntar se deviam fazê-lo.', 68974);
